func (s *server) handleStatus(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		w.Header().Set("Allow", "GET")
		writeJSON(w, http.StatusMethodNotAllowed, apiResponse{Error: "Метод не поддерживается"})
		return
	}
	writeJSON(w, http.StatusOK, apiResponse{Model: s.model, Models: s.models})
}

func (s *server) handleProfiles(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		w.Header().Set("Allow", "GET")
		writeJSON(w, 405, apiResponse{Error: "Метод не поддерживается"})
		return
	}
	a, err := s.agentFor(w, r)
	if err != nil {
		writeJSON(w, 500, apiResponse{Error: "Не удалось загрузить сессию"})
		return
	}
	view, err := a.Profiles()
	if err != nil {
		writeJSON(w, 500, apiResponse{Error: "Не удалось загрузить профили"})
		return
	}
	writeJSON(w, 200, apiResponse{Profiles: &view})
}

func (s *server) handleMCPMutation(w http.ResponseWriter, r *http.Request) {
	if !allowAPIRequest(w, r, http.MethodPost) {
		return
	}
	if s.mcpStore == nil {
		writeJSON(w, 503, apiResponse{Error: "Хранилище MCP не подключено"})
		return
	}
	if !hasJSONContentType(r) {
		writeJSON(w, 415, apiResponse{Error: "Ожидается application/json"})
		return
	}
	var request struct {
		ID           string   `json:"id"`
		Version      int      `json:"version"`
		Name         string   `json:"name"`
		URL          string   `json:"url"`
		Token        string   `json:"token"`
		ClearToken   bool     `json:"clearToken"`
		Enabled      bool     `json:"enabled"`
		AllowedTools []string `json:"allowedTools"`
	}
	r.Body = http.MaxBytesReader(w, r.Body, 16<<10)
	decoder := json.NewDecoder(r.Body)
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&request); err != nil {
		writeJSON(w, 400, apiResponse{Error: "Некорректные настройки MCP"})
		return
	}
	if err := decoder.Decode(&struct{}{}); err != io.EOF {
		writeJSON(w, 400, apiResponse{Error: "Ожидается один JSON-объект"})
		return
	}
	var err error
	view := &mcpView{}
	switch r.URL.Path {
	case "/api/mcp/save":
		_, err = s.mcpStore.Save(mcpclient.Connection{ID: request.ID, Name: request.Name, URL: request.URL, Version: request.Version}, request.Token, request.ClearToken)
	case "/api/mcp/delete":
